<?php
require_once __DIR__.'/../config/conexao.php';require_once __DIR__.'/../includes/auth.php';exigir_conta_ativa($pdo,'admin');
$filtro=$_GET['status']??'pendente';$validos=['pendente','aprovado','recusado','cancelado','todos'];if(!in_array($filtro,$validos,true))$filtro='pendente';
$sql='SELECT p.*,u.nome AS leitor,l.titulo,v.disponivel FROM pedido_emprestimo p JOIN usuario u ON u.id_usuario=p.id_usuario JOIN livro l ON l.id_livro=p.id_livro LEFT JOIN vw_livro_disponivel v ON v.id_livro=p.id_livro';
if($filtro!=='todos'){$sql.=' WHERE p.status=?';}$sql.=' ORDER BY p.id_pedido DESC';
$st=$pdo->prepare($sql);$st->execute($filtro==='todos'?[]:[$filtro]);$pedidos=$st->fetchAll();
cabecalho('Solicitações','pedidos');
?>
<div class="section-heading"><div><span class="eyebrow">ANÁLISE DE PEDIDOS</span><h2>Solicitações dos leitores</h2><p class="muted">Aprove somente quando a retirada do exemplar for confirmada.</p></div></div>
<div class="tabs"><?php foreach(['pendente'=>'Pendentes','aprovado'=>'Aprovados','recusado'=>'Recusados','cancelado'=>'Cancelados','todos'=>'Todos'] as $k=>$v): ?><a class="<?= $filtro===$k?'selected':'' ?>" href="?status=<?= e($k) ?>"><?= e($v) ?></a><?php endforeach; ?></div>
<div class="panel table-wrap"><?php if(!$pedidos): ?><div class="empty-state">Nenhuma solicitação nesta categoria.</div><?php else: ?><table><thead><tr><th>Leitor</th><th>Livro</th><th>Data</th><th>Disponíveis</th><th>Status</th><th>Decisão</th></tr></thead><tbody>
<?php foreach($pedidos as $p): ?><tr><td class="strong"><?= e($p['leitor']) ?></td><td><?= e($p['titulo']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($p['solicitado_em']))) ?></td><td><?= (int)$p['disponivel'] ?></td><td><span class="status <?= $p['status']==='aprovado'?'status-ok':($p['status']==='recusado'?'status-late':'status-open') ?>"><?= e(ucfirst($p['status'])) ?></span></td><td><?php if($p['status']==='pendente'): ?><form method="post" action="decidir.php" class="decision-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id_pedido'] ?>"><input name="observacao" maxlength="500" placeholder="Observação (opcional)"><button class="button button-small button-primary" name="decisao" value="aprovar" onclick="return confirm('Confirmar retirada e aprovar o empréstimo?')">Aprovar</button><button class="button button-small button-ghost" name="decisao" value="recusar" onclick="return confirm('Recusar solicitação?')">Recusar</button></form><?php else: ?><?= e($p['observacao']?:'—') ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div><?php rodape(); ?>
